DO $$
DECLARE
  v_0 UUID;
  v_1 UUID;
  v_2 UUID;
  v_3 UUID;
BEGIN
  SELECT vendor_id INTO v_0 FROM vendors WHERE name = 'TrackMaster Corp' LIMIT 1;
  SELECT vendor_id INTO v_1 FROM vendors WHERE name = 'PadTech Industries' LIMIT 1;
  SELECT vendor_id INTO v_2 FROM vendors WHERE name = 'ClipCorp Solutions' LIMIT 1;
  SELECT vendor_id INTO v_3 FROM vendors WHERE name = 'RailTech Industries' LIMIT 1;
END $$;
